# noout will make it not display the cert
openssl x509 -in 2048b-rsa-example-cert.der -text -noout

# i can also...
# convert to PEM
openssl x509 -in 2048b-rsa-example-cert.der -out certainlynot.pem
openssl x509 -in certainlynot.pem -text -noout

# output modulus in hex
openssl x509 -in 2048b-rsa-example-cert.der -text -noout -modulus


python3 -c "print(int('$Modulus', 16))"

